func TestEnumAccountStatus(t *testing.T) {
	t.Run("NewFromString_active", func(t *testing.T) {
		t.Parallel()
		val, err := NewAccountStatusFromString("active")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AccountStatus("active"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_warning", func(t *testing.T) {
		t.Parallel()
		val, err := NewAccountStatusFromString("warning")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AccountStatus("warning"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_locked", func(t *testing.T) {
		t.Parallel()
		val, err := NewAccountStatusFromString("locked")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, AccountStatus("locked"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewAccountStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewAccountStatusFromString("active")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

